import { PrismaClient } from "@prisma/client";
import { loadLocalEnv } from "../src/shared/lib/load-env";

loadLocalEnv();

const prisma = new PrismaClient();

/**
 * Clears seedable content so it can be rebuilt from the seed.
 *
 * This is recoverable by design: everything removed here is generated by
 * `prisma/seed.ts`. It deliberately leaves `User` and `GenerationJob` alone.
 * Vocabulary reviews cascade with their vocabulary rows, so SRS history is lost;
 * that is printed before the fact instead of being a surprise.
 */
async function main() {
  const before = {
    questions: await prisma.question.count(),
    lessons: await prisma.lesson.count(),
    vocabulary: await prisma.vocabulary.count(),
    modules: await prisma.module.count(),
    vocabularyReviews: await prisma.vocabularyReview.count(),
  };

  console.log("content to clear:", JSON.stringify(before));
  console.log("kept: users and generation jobs");

  await prisma.vocabularyReview.deleteMany({});
  await prisma.question.deleteMany({});
  await prisma.lesson.deleteMany({});
  await prisma.vocabulary.deleteMany({});
  await prisma.module.deleteMany({});

  console.log("content cleared; run the seed to rebuild it");
}

main()
  .catch((error) => {
    console.error(error);
    process.exit(1);
  })
  .finally(() => prisma.$disconnect());
